#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <esp_sleep.h>
#define OLED_W 128
#define OLED_H 64
Adafruit_SSD1306 display(OLED_W, OLED_H, &Wire, -1);
const int PIN_SOIL = D2; // GPIO4 ADC - AOUT датчика
const int PIN_LED_RED = D10; // GPIO10
const int PIN_LED_GREEN = D3; // GPIO5
const int PIN_LED_BLUE = D6; // TX GPIO21 - синий "влажно"
const int PIN_BUZZER = D7; // RX GPIO20 через NPN
const int PIN_BTN = D1; // GPIO3
int VAL_DRY = 2600;
int VAL_WET = 1300;
int THRESH_DRY = 30;
int THRESH_WET = 70;
int readMoisturePercent(){ long sum=0; for(int i=0;i<16;i++){ sum+=analogRead(PIN_SOIL); delay(5);} int raw=sum/16; int pct=map(raw,VAL_DRY,VAL_WET,0,100); return constrain(pct,0,100);}
void updateLeds(int pct){ digitalWrite(PIN_LED_RED, pct<THRESH_DRY?HIGH:LOW); digitalWrite(PIN_LED_GREEN, (pct>=THRESH_DRY && pct<=THRESH_WET)?HIGH:LOW); digitalWrite(PIN_LED_BLUE, pct>THRESH_WET?HIGH:LOW); }
void goSleep(){ esp_sleep_enable_timer_wakeup(10ULL*60ULL*1000000ULL); esp_deep_sleep_enable_gpio_wakeup(1ULL<<3, ESP_GPIO_WAKEUP_GPIO_LOW); display.ssd1306_command(SSD1306_DISPLAYOFF); digitalWrite(PIN_LED_RED,LOW); digitalWrite(PIN_LED_GREEN,LOW); digitalWrite(PIN_LED_BLUE,LOW); digitalWrite(PIN_BUZZER,LOW); esp_deep_sleep_start(); }
void setup(){
 pinMode(PIN_LED_RED,OUTPUT); pinMode(PIN_LED_GREEN,OUTPUT); pinMode(PIN_LED_BLUE,OUTPUT);
 pinMode(PIN_BUZZER,OUTPUT); pinMode(PIN_BTN,INPUT_PULLUP); pinMode(PIN_SOIL,INPUT);
 Wire.begin();
 display.begin(SSD1306_SWITCHCAPVCC,0x3C);
 int pct=readMoisturePercent(); updateLeds(pct); bool isDry=pct<THRESH_DRY; bool isWet=pct>THRESH_WET;
 display.clearDisplay(); display.setTextSize(2); display.setCursor(0,0); display.print(pct); display.print(" %");
 display.setTextSize(1); display.setCursor(0,22); if(isDry) display.println("SUHO - POLEI!"); else if(isWet) display.println("Vlazhno - OK"); else display.println("Normalno");
 display.setCursor(0,36); display.print("ADC:"); display.print(analogRead(PIN_SOIL)); display.display();
 if(isDry){ for(int i=0;i<3;i++){ digitalWrite(PIN_BUZZER,HIGH); delay(200); digitalWrite(PIN_BUZZER,LOW); delay(200);} }
 delay(3000); if(digitalRead(PIN_BTN)==LOW) delay(500); else goSleep();
}
void loop(){ if(digitalRead(PIN_BTN)==LOW){ delay(200); goSleep(); } delay(100); }
